// Code generated once from START.EXE's data segment (offsets in the
// comments); the tables are maintained here by hand from now on.

package rules1e

// The tables' value types: each keeps the DOS byte's width.
type (
	Dir        uint8 // one of the eight directions (DirDX, DirDY), 8: none
	GroundProp uint8 // a ground type's property: move cost (0xFF wall), height, sight, ...
	SpellProp  uint8 // a spell record's field: class, level, ...
	Terrain    uint8 // an overland map square's terrain
	ClassBits  uint8 // class bits (classMask): the classes an item or roll is for
	Colour     uint8 // an EGA colour number
)

// aiStepPattern: the five direction offsets (from the target's direction)
// a moving combatant tries in turn, steps 1..5.
type aiStepPattern [5]Dir

// AI step patterns by pattern number (DS:02AE). The original indexes
// DS:02AE[pattern*5+step] with step 1..5, so each pattern's steps start one
// byte into its 5-byte row and end on the next row's first byte (pattern
// 6's last step is DS:02D1); laid out here as they are read.
var aiStepPatterns = [7]aiStepPattern{
	{0, 0, 0, 0, 0},
	{8, 7, 6, 1, 2},
	{8, 1, 2, 7, 6},
	{7, 1, 8, 6, 2},
	{1, 7, 8, 2, 6},
	{8, 7, 6, 5, 4},
	{8, 1, 2, 3, 4},
}

