// default combat icon colours (DS:3CF5).
var defaultIconColours = [7]Colour{0x0A, 0x01, 0x02, 0x03, 0x04, 0x06, 0x07}

// raceLimits (DS:3DA3): ability limits by race (row 0 is not a race).

// classes open to each race: [0] count, then the classes (DS:3E17).
// Paladin (3), Ranger (4) and Cleric/Ranger (10) added as in CotAB (unk_1A1D4).

// startAge (DS:3E5B+race*0x1C+class*4): base age and dice, by race and single class.
// The half-elf ranger, 0 in both PoR and CotAB, takes the half-elf fighter's.

// age categories by race: middle-aged, old, venerable ... (DS:3F31).

// ability minimums, by class (DS:3F81).

// alignments open to each class: [0] count, then the alignments (DS:3FE7). Rangers are good only, as in CotAB.

// raceLimit is a race's row of raceLimits. Strength limits used to differ by
// gender (the women's are kept in the comments); everyone gets the men's now.

// ageDice is a starting age: Base + Count dice of Sides.

// limits returns the race's minimum and maximum of ability i (0 strength).

// ClassName (extra) is classNames[b], "" for a class byte past the table
// (a damaged save).
func ClassName(b ClassID) string {
	if int(b) < len(ClassNames) {
		return ClassNames[b]
	}
	return ""
}
